// AI Chat Exporter 1.2.14: Google AI export for iPhone Shortcuts. Generated by scripts/build-mobile.js.
// Shared by the extension and the copyable console exporter.
globalThis.AIChatExporterBrowserAdapters = (() => {
  const label = text => String(text || "").replace(/[[\]\r\n]/g, " ").trim();
  function imageLabel(image, isGemini = false) {
    // Google puts <b> highlighting inside image descriptions.
    const alt = (image.getAttribute("alt") || "").replace(/<\/?[a-z][^>]*>/gi, "").trim();
    // Generic accessibility labels are not evidence of image provenance.
    if (isGemini && /^(?:an?\s+)?(?:ai[- ]generated(?:\s+image)?|generated\s+(?:image|by\s+gemini)|image\s+generated\s+by\s+(?:ai|gemini))[.!]?$/i.test(alt)) return "Image";
    return label(alt) || "Image";
  }
  const QUERY = '[jsname="eFVkfb"], [jsname="y5v2y"]';
  function isGoogleSearch(href) {
    try { const u = new URL(href); return /^(www\.)?google\.com$/.test(u.hostname) && /^\/(search|aimode)\/?$/.test(u.pathname); }
    catch { return false; }
  }
  function extractGoogle(doc, href, { includeMedia = true } = {}) {
    if (!isGoogleSearch(href)) throw new Error("Not a supported Google Search page.");
    const url = new URL(href);
    const mode = url.searchParams.get("udm") === "50" || url.pathname.startsWith("/aimode") || !!doc.querySelector('[jsname="RH7zg"]');
    const remoteQueue = [], media = new Map();
    function link(value) {
      if (!value) return "";
      try {
        let result = new URL(value, href);
        if (/^(www\.)?google\.com$/.test(result.hostname) && result.pathname === "/url") result = new URL(result.searchParams.get("q") || result.searchParams.get("url"));
        return /^(https?:|data:|blob:)$/.test(result.protocol) ? result.href.replace(/[<>\r\n]/g, "") : "";
      } catch { return ""; }
    }
    function render(node) {
      if (node.nodeType === 3) return node.textContent;
      if (node.nodeType !== 1) return "";
      const tag = node.tagName.toLowerCase();
      // Google's image viewer is a button, but its picture is answer content.
      if (node.matches('[data-im][role="button"]')) return [...node.querySelectorAll("img")].map(render).join("\n");
      // A tappable term inside a sentence (an unlabelled span button) is text.
      if (tag === "span" && node.getAttribute("role") === "button" && !node.hasAttribute("aria-label")) return [...node.childNodes].map(render).join("");
      if (["script", "style", "svg", "button", "input", "textarea", "noscript"].includes(tag) ||
          node.matches('[hidden],[role="button"],[role="checkbox"],[role="dialog"],[aria-hidden="true"],[data-container-id="rhs-col"],[data-xid="Gd7Hsc"]') ||
          // The mobile page lists source cards inside the answer; desktop shows
          // them in the sidebar (rhs-col). Answer lists are ul/ol elements.
          (node.matches('[role="list"]') && !/^(ul|ol)$/.test(tag)) ||
          /(?:^|;)\s*display\s*:\s*none\b/i.test(node.getAttribute("style") || "")) return "";
      if (tag === "img") {
        const alt = imageLabel(node);
        const displayed = link(node.currentSrc || node.getAttribute("src") || node.getAttribute("data-src"));
        let descriptor;
        try { descriptor = JSON.parse(node.closest("[data-im]")?.getAttribute("data-im") || "null"); } catch { /* use rendered image */ }
        const src = link(descriptor?.[3]?.[0]) || displayed;
        const sourceUrl = link(descriptor?.[4]?.["2003"]?.[2]);
        if (!src || /favicon|logo|icon/i.test(alt) || (node.getAttribute("width") && Number(node.getAttribute("width")) <= 32)) return "";
        // A tiny inline GIF is a placeholder for an image that has not loaded.
        if (/^data:image\/gif/i.test(src) && src.length < 512) return "";
        // Safari on iPhone gets some pictures inlined as data: URLs of several
        // hundred KB. Without media files there is no link to keep, so name
        // the picture instead of pasting it into the text.
        if (!includeMedia && /^data:/i.test(src)) return `\n\n[Image: ${alt}]${sourceUrl ? `\n[Image source](<${sourceUrl}>)` : ""}\n\n`;
        let target = src;
        if (includeMedia) {
          if (!media.has(src)) {
            const ext = (src.match(/^data:image\/(png|jpe?g|gif|webp|avif)[;,]/i) || src.match(/\.(png|jpe?g|gif|webp|avif)(?:[?#]|$)/i))?.[1] || "png";
            const filename = `google-image-${media.size + 1}.${ext}`;
            media.set(src, filename);
            remoteQueue.push({ url: src, fallbackUrl: displayed !== src ? displayed : "", filename, kind: "image", alt });
          }
          target = `media/${media.get(src)}`;
        }
        return `\n\n![${alt}](${target})${sourceUrl ? `\n[Image source](<${sourceUrl}>)` : ""}\n\n`;
      }
      if (tag === "pre") {
        const body = node.textContent.trim();
        const fence = "`".repeat(Math.max(3, ...[...body.matchAll(/`+/g)].map(m => m[0].length + 1)));
        return `\n\n${fence}\n${body}\n${fence}\n\n`;
      }
      if (tag === "table") {
        const rows = [...node.querySelectorAll("tr")].filter(row => row.closest("table") === node).map(row =>
          [...row.children].filter(c => /^(TD|TH)$/.test(c.tagName)).map(cell =>
            [...cell.childNodes].map(render).join("").trim().replace(/\|/g, "\\|").replace(/\n/g, "<br>")));
        if (!rows.length) return "";
        const width = Math.max(...rows.map(row => row.length));
        const line = row => "| " + Array.from({ length: width }, (_, i) => row[i] || "").join(" | ") + " |";
        return "\n\n" + [line(rows[0]), line(Array(width).fill("---")), ...rows.slice(1).map(line)].join("\n") + "\n\n";
      }
      const text = [...node.childNodes].map(render).join("");
      if (tag === "a") {
        const target = link(node.getAttribute("href"));
        return target ? `[${text.trim() || label(node.getAttribute("aria-label")) || "Source"}](<${target}>)` : text;
      }
      if (tag === "br") return "\n";
      if (tag === "li") return `\n- ${text.trim()}\n`;
      if (tag === "strong" || tag === "b") return text.trim() ? `**${text.trim()}**` : "";
      if (tag === "code") return `\`${text}\``;
      if (tag === "p") return "\n\n" + text + "\n\n";
      if (tag === "th" || tag === "td") return text.replace(/\|/g, "\\|").trim() + " | ";
      if (tag === "tr") return "\n| " + text;
      if (/^h[1-6]$/.test(tag) || node.getAttribute("role") === "heading") return `\n\n### ${text.trim()}\n\n`;
      if (["div", "section", "ul", "ol"].includes(tag)) return "\n" + text + "\n";
      return text;
    }
    // Adjacent bold runs ("**a****b**") read as one bold phrase.
    // Punctuation left alone on its own line belongs to the line before.
    const clean = node => render(node).replace(/\*\*\*\*/g, "").replace(/[ \t]+\n/g, "\n").replace(/\n+([.,;:!?])(?=\n|$)/g, "$1").replace(/\n{3,}/g, "\n\n").trim();
    const messages = [];
    const siteName = mode ? "Google AI Mode" : "Google AI Overview";
    if (mode) {
      // Each live RH7zg block owns a query and main answer column. The RHS
      // contains repeated source snippets, not additional assistant turns.
      const turns = [...doc.querySelectorAll('[jsname="RH7zg"]')];
      if (!turns.length) throw new Error("AI Mode conversation has not loaded, or its layout is unsupported.");
      for (const turn of turns) {
        // Desktop wraps the question in eFVkfb; the mobile page uses a
        // y5v2y heading instead.
        const query = turn.querySelector(QUERY);
        const answer = turn.querySelector('[data-container-id="main-col"], [jsname="KFl8ub"]');
        if (!query || !answer || answer.querySelector('[data-complete="false"]') || !clean(answer)) throw new Error("An AI Mode turn is incomplete. Wait for the response to finish and retry.");
        messages.push({ role: "## You", text: query.textContent.trim() }, { role: `## ${siteName}`, text: clean(answer) });
      }
    } else {
      const answer = doc.querySelector('#m-x-content [data-container-id="main-col"], #m-x-content [jsname="KFl8ub"]');
      if (!answer) throw new Error("No AI Overview found. Ordinary search results are not an AI conversation.");
      const text = clean(answer);
      if (!text) throw new Error("The AI Overview has not loaded yet.");
      messages.push({ role: "## You", text: url.searchParams.get("q") || "Google Search" }, { role: `## ${siteName}`, text });
    }
    return { title: messages[0].text, siteName, date: new Date().toISOString(), messageCount: messages.length,
      messages, savedMedia: [], remoteQueue, failedFetches: [] };
  }
  async function exportGoogle(doc, href, options = {}) {
    const signal = options.signal;
    const cancelled = () => Object.assign(new Error("Export cancelled."), { name: "AbortError" });
    const wait = () => new Promise((resolve, reject) => {
      const abort = () => { clearTimeout(timer); reject(cancelled()); };
      const timer = setTimeout(() => { signal?.removeEventListener("abort", abort); resolve(); }, 250);
      signal?.addEventListener("abort", abort, { once: true });
      if (signal?.aborted) abort();
    });
    const scroll = doc.scrollingElement || doc.documentElement;
    const original = scroll.scrollTop;
    // An AI Overview starts collapsed behind "Show more", and Google marks the
    // collapsed part aria-hidden until it is expanded. Expand it once. Doing so
    // adds a #fragment to the address, which is not a different page.
    for (const button of doc.querySelectorAll('[role="button"][aria-expanded="false"][aria-controls="m-x-content"]')) button.click?.();
    const samePage = (a, b) => String(a).split("#")[0] === String(b).split("#")[0];
    const observedQueries = new Set();
    let last = "", stable = 0;
    try {
      // No tab activation, window movement, or clipboard dependency.
      for (let i = 0; i < 32; i++) {
        if (signal?.aborted) throw cancelled();
        if (doc.location?.href && !samePage(doc.location.href, href)) throw new Error("The Google page changed during export. Export the intended conversation again.");
        scroll.scrollTop = i < 12 ? 0 : scroll.scrollHeight;
        await wait();
        const data = extractGoogle(doc, href, options);
        for (const turn of doc.querySelectorAll('[jsname="RH7zg"]')) { const query = turn.querySelector(QUERY); if (query) observedQueries.add(query); }
        const signature = JSON.stringify(data.messages);
        stable = signature === last ? stable + 1 : 0;
        last = signature;
        if (i >= 15 && stable >= 4) {
          if ([...observedQueries].some(query => !doc.contains(query))) throw new Error("Google unloaded earlier turns during the scan. No partial history was exported.");
          return data;
        }
      }
      throw new Error("Google's response is still changing. Wait until it finishes before exporting.");
    } finally { scroll.scrollTop = original; }
  }
  return { imageLabel, isGoogleSearch, extractGoogle, exportGoogle };
})();

// Runs inside an iOS Shortcut's "Run JavaScript on Web Page" action on a
// Google AI Mode or AI Overview page in Safari. It reads the conversation with
// the same Google adapter as the Chrome extension and returns the Markdown,
// formatted like the extension's .md files, for the Shortcut to save.
// scripts/build-mobile.js places browserAdapters.js above this file.
//
// Safari gives this action two seconds in total: running the script and
// sending its reply back to Shortcuts. So the script reads the page as it is
// instead of waiting for it to settle the way the extension does. A page that
// is ready is read once, with no timer. Expanding a collapsed AI Overview takes
// Google a few milliseconds, and an answer still being written gets until
// LIMIT ms to finish.
(async () => {
  const LIMIT = 700;
  // Apple's wrapper for this action (ActionExtension.js in the Shortcuts app)
  // sends the page's full HTML back with every completion() result. Google's
  // pages are several MB of HTML, which can use up the two seconds on their
  // own, so while the result is handed over the page HTML reads as empty to
  // the wrapper. The page itself is untouched, and outerHTML works normally
  // again as soon as completion() returns.
  const done = value => {
    const send = typeof completion === "function" ? completion : console.log;
    const root = document.documentElement;
    let hidden = false;
    try {
      Object.defineProperty(root, "outerHTML", { configurable: true, get: () => "" });
      hidden = true;
    } catch { /* The page HTML is sent along as before. */ }
    try { send(JSON.stringify(value)); } finally { if (hidden) delete root.outerHTML; }
  };
  try {
    const adapters = globalThis.AIChatExporterBrowserAdapters;
    // Expanding an AI Overview adds a #fragment, so keep the address from now.
    const href = location.href;
    if (!adapters.isGoogleSearch(href)) throw new Error("Open a Google AI Mode or AI Overview answer in Safari, then run this from the Share menu.");
    // An AI Overview starts collapsed behind "Show more", with the rest of the
    // answer marked aria-hidden. The button keeps aria-expanded="false" after
    // it expands, so the reads below show when the text has appeared.
    const expanding = [...document.querySelectorAll('[role="button"][aria-expanded="false"][aria-controls="m-x-content"]')];
    for (const button of expanding) button.click();
    const start = Date.now();
    let data, previous;
    for (;;) {
      let problem;
      try { data = adapters.extractGoogle(document, href, { includeMedia: false }); }
      catch (error) { problem = error; data = null; }
      const signature = data && JSON.stringify(data.messages);
      if (data && (!expanding.length || signature === previous)) break;
      if (Date.now() - start >= LIMIT) {
        if (data) break;
        throw problem;
      }
      previous = signature;
      await new Promise(resolve => setTimeout(resolve, 50));
    }
    const nl = "\n";
    let md = "---" + nl;
    md += "title: " + JSON.stringify(data.title) + nl;
    md += "source: " + data.siteName + nl;
    md += "source_url: " + JSON.stringify(href) + nl;
    md += "exporter_version: " + JSON.stringify("1.2.14") + nl;
    md += "exported_at: " + data.date + nl;
    md += "message_count: " + data.messageCount + nl;
    md += "media_count: 0" + nl;
    md += "---" + nl + nl;
    md += "# " + data.title + nl + nl;
    data.messages.forEach((message, index) => {
      md += message.role + nl + nl + message.text + nl + nl;
      if (index < data.messages.length - 1) md += "---" + nl + nl;
    });
    const name = data.title.replace(/[^a-z0-9]+/gi, "-").replace(/^-|-$/g, "").toLowerCase().slice(0, 60) || "chat-export";
    done({ filename: name + ".md", markdown: md });
  } catch (error) {
    done({ error: String(error && error.message || error) });
  }
})();
